function finishInputGroup(group){if(pendingInput!==group||!playing||autoPlay||$('#pause-ui')){if(pendingInput===group)pendingInput=null;return}pendingInput=null;const candidates=chart.notes.map((n,i)=>({n,i,delta:Math.abs(n.time-group.time)})).filter(x=>!x.n.hit&&!x.n.missed&&x.delta<=JUDGMENT_WINDOWS.good);if(!candidates.length){markInputMiss([]);return}const closest=candidates.reduce((best,x)=>x.delta<best.delta?x:best);const required=candidates.filter(x=>Math.abs(x.n.time-closest.n.time)<=CHORD_TIME_TOLERANCE);const requiredLanes=new Set(required.map(x=>x.n.lane));const isExact=requiredLanes.size===group.lanes.size&&[...requiredLanes].every(l=>group.lanes.has(l));if(!isExact){markInputMiss(required.map(x=>x.i));return}const x=closest.delta<=JUDGMENT_WINDOWS.perfect?'PERFECT':closest.delta<=JUDGMENT_WINDOWS.great?'GREAT':'GOOD';required.forEach(note=>resolveHit(note.i,x))}
function queueManualInput(lane){if(!playing||autoPlay||$('#pause-ui'))return;if(!pendingInput){const group={lanes:new Set(),time:audio.currentTime,timer:null};pendingInput=group;group.timer=setTimeout(()=>finishInputGroup(group),INPUT_GROUP_WINDOW)}pendingInput.lanes.add(lane)}
function judge(x){counts[x]++;if(x==='MISS'){combo=0;lastRecoveryCombo=0;if(applyMissDamage())return}else{combo++;maxCombo=Math.max(maxCombo,combo);score+=x==='PERFECT'?1000:x==='GREAT'?700:400;applyComboRecovery()}hud();if(x!=='MISS'&&combo>=100&&combo%100===0)playComboMilestoneSound(Math.min(3,Math.floor(combo/100)));judgeFx(x);if(x!=='MISS'){const c=$('#combo');c.className=`combo-pop ${combo%100===0?'milestone':''}`;setTimeout(()=>c.className='',260)}}
function completePlayResult(clear,persist=true){if(!playing)return false;playing=false;cancelAnimationFrame(raf);audio.pause();pendingInput=null;if(!persist){nodes.forEach(n=>n.remove());nodes.clear();document.querySelectorAll('.hit-burst,.lane-flash').forEach(n=>n.remove())}let max=getChartMaximums(chart)?.maxScore||0,rate=max?score/max:0,resultJacket=$('#result-jacket');if(persist)finalizeRun({outcome:clear?'clear':'failed',score,rate,maxCombo,judgements:counts,hp:currentHP});else if(currentRun)currentRun.finalized=true;if(!resultJacket){resultJacket=document.createElement('img');resultJacket.id='result-jacket';resultJacket.alt='楽曲ジャケット';$('#result-title').before(resultJacket)}resultJacket.hidden=!clear||!song.jacket;if(!resultJacket.hidden)resultJacket.src=song.jacket;$('#result-kind').textContent=clear?'CLEAR!!':'FAILED';$('#result-title').textContent=song.title;$('#result-stats').textContent=`SCORE ${score} / ${max}　RATE ${(rate*100).toFixed(1)}%　PERFECT ${counts.PERFECT}　GREAT ${counts.GREAT}　GOOD ${counts.GOOD}　MISS ${counts.MISS}　MAX COMBO ${maxCombo}`;show('result');$('#result-screen').dataset.clear=clear?'1':'0';return true}
function finish(){if(!playing)return;const max=getChartMaximums(chart)?.maxScore||0,rate=max?score/max:0;completePlayResult(rate>=(song.clearRate??data.settings.clearRate))}
function move(n){const cardCount=songs.length+1;si=(si+n+cardCount)%cardCount;renderSelect()}function returnToTitleFromSelect(){show('title')}function returnToTitleFromBonus(){show('title')}
document.addEventListener('click',e=>{const card=e.target.closest?.('[data-song-card-index]');if(!card||screen!=='select')return;const index=Number(card.dataset.songCardIndex);if(index===si){if(selected().playable!==false)show('difficulty')}else if(Number.isInteger(index)&&index>=0&&index<=songs.length){si=index;renderSelect()}});
window.addEventListener?.('resize',()=>{if(screen!=='select')return;cancelAnimationFrame(selectCenterFrame);selectCenterFrame=requestAnimationFrame(()=>centerSelectedSongCard('auto'))});
function key(e){if(e.repeat)return;if(screen==='bonus'){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();moveBonus(e.key==='ArrowLeft'?-1:1)}else if(e.key==='Escape'){e.preventDefault();returnToTitleFromBonus()}return}if(screen==='title'&&hasBonusUnlocked()&&(e.key==='ArrowUp'||e.key==='ArrowDown')){e.preventDefault();titleSelectionIndex=titleSelectionIndex?0:1;renderTitle();return}if(screen==='play'){let l=keys.indexOf(e.key.toLowerCase());if(l>=0){e.preventDefault();queueManualInput(l)}return}if(screen==='select'&&e.key==='Enter'&&e.target.closest?.('[data-action="select-title"]')){e.preventDefault();returnToTitleFromSelect();return}if(e.key==='Enter'){if(screen==='title')show(titleSelectionIndex===1&&hasBonusUnlocked()?'bonus':'select');else if(screen==='select'&&selected().playable!==false)show('difficulty');else if(screen==='difficulty')startGame();else if(screen==='result')show($('#result-screen').dataset.clear==='1'?'select':'gameover');else if(screen==='gameover')show('title')}if(e.key==='Escape'){if(screen==='select')returnToTitleFromSelect();if(screen==='difficulty')show('select')}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();let n=e.key==='ArrowLeft'?-1:1;if(screen==='select')move(e.key==='ArrowLeft'||e.key==='ArrowUp'?-1:1);if(screen==='difficulty'){if(e.key==='ArrowDown')difficultySelectionRow=1;else if(e.key==='ArrowUp')difficultySelectionRow=0;else if(difficultySelectionRow===0)di=(di+n+3)%3;else autoPlay=n>0;renderDifficulty()}}}
function pause(){if(!playing||$('#pause-ui'))return;playing=false;audio.pause();pendingInput=null;cancelAnimationFrame(raf);const p=document.createElement('div');p.id='pause-ui';p.innerHTML='<h1>PAUSED</h1><button id="pause-continue">RESUME</button><button id="pause-retry">RETRY</button><button id="pause-quit">TITLE</button>';$('#play-screen').append(p);pauseSelectedIndex=0;renderPauseSelection();$('#pause-continue').onclick=()=>{p.remove();beginCountdown(()=>{playing=true;audio.play().then(render).catch(()=>{playing=false;show('title')})})};$('#pause-retry').onclick=()=>{p.remove();playing=false;currentRun=null;audio.pause();audio.currentTime=0;pendingInput=null;cancelAnimationFrame(raf);nodes.forEach(n=>n.remove());nodes.clear();document.querySelectorAll('.hit-burst,.lane-flash').forEach(n=>n.remove());startGame()};$('#pause-quit').onclick=()=>{p.remove();playing=false;currentRun=null;audio.pause();audio.currentTime=0;pendingInput=null;cancelAnimationFrame(raf);nodes.forEach(n=>n.remove());nodes.clear();document.querySelectorAll('.hit-burst,.lane-flash').forEach(n=>n.remove());show('title')}}document.addEventListener('keydown',key);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&screen==='play')pause()});document.addEventListener('click',e=>{let a=e.target.closest?.('[data-action]')?.dataset.action;if(a==='mobile-pause'&&screen==='play')pause();if(a==='title-start')show('select');if(a==='select-title'&&screen==='select')returnToTitleFromSelect();if(a==='bonus-title'&&screen==='bonus')returnToTitleFromBonus();if(a==='bonus-track'&&hasBonusUnlocked())show('bonus');if(a==='bonus-prev')moveBonus(-1);if(a==='bonus-next')moveBonus(1);if(a==='result-continue')show($('#result-screen').dataset.clear==='1'?'select':'gameover');if(a==='gameover-title')show('title')});
window.rhythmGameBridge=Object.freeze({
  getScreen:()=>screen,
  isPlaying:()=>playing,
  isPaused:()=>!!$('#pause-ui'),
  getCurrentRun:()=>currentRun,
  onScreenChange:listener=>gameEvents.screen.push(listener),
  onRunStart:listener=>gameEvents.runStart.push(listener),
  completePlayResult,
  createDefaultSave,
  replaceSaveData:value=>{saveData=value},
  getDifficultyRecord,
  saveGame,
  show,
  ensureAudioContext:ensurePerfectAudio
});
init();
